CREATE TABLE IF NOT EXISTS "public"."notification_kind" (
  "id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "name" TEXT NOT NULL UNIQUE,
  PRIMARY KEY ("id")
);

INSERT INTO notification_kind (id, name)
VALUES
